$ErrorActionPreference='Stop'
$js=@'
const port=17447,url="https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/sdam/posutochno";
const version=await (await fetch("http://127.0.0.1:"+port+"/json/version")).json();
const ws=new WebSocket(version.webSocketDebuggerUrl);
await new Promise((yes,no)=>{ws.addEventListener("open",yes,{once:true});ws.addEventListener("error",no,{once:true})});
const p=new Promise((yes,no)=>{ws.addEventListener("message",e=>{try{const data=JSON.parse(e.data);if(data.id===100){yes(data)}}catch{}},{once:false});setTimeout(()=>no(Error("timeout")),7000)});
ws.send(JSON.stringify({id:100,method:"Target.createTarget",params:{url,background:true,newWindow:false}}));
const out=await p;ws.close();console.log(JSON.stringify({ok:!!out.result?.targetId,target_id:out.result?.targetId||null,error_code:out.error?.code||null,url}));
'@
$tmp=Join-Path $env:TEMP 'pc-test-avito-direct-cdp.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
